```java
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/

class Solution {
    public int maxPathSum(TreeNode root) {
        TreeNode node = new TreeNode(Integer.MIN_VALUE);
        maxPath(root, node);
        return node.data;
    }
    int maxPath(TreeNode root, TreeNode node){
        if(root == null) return 0;
        int left = Math.max(0, maxPath(root.left, node));
        int right = Math.max(0, maxPath(root.right, node));
        node.data = Math.max(node.data, (root.data + left + right));
        return root.data + Math.max(left, right);
    }
}
```

